void __fastcall SHA1_Init(uint32_t * pState) {
    *pState = 0x67452301;
    pState[1] = 0xefcdab89;
    pState[2] = 0x98badcfe;
    pState[3] = 0x10325476;
    pState[4] = 0xc3d2e1f0;
    pState[6] = 0;
    pState[5] = 0;
}

void __fastcall SHA1_Update(uint32_t * pShaCtx, void * pData, uint32_t nByteLen) {
    size_t nProcessed;
    uint32_t nBufOffset = pShaCtx[5] + nByteLen * 8;
    uint32_t nBitLo = pShaCtx[5] >> 3 & 0x3f;
    pShaCtx[5] = nBufOffset;
    if (nBufOffset < nByteLen * 8) {
      pShaCtx[6]++;
    }

    pShaCtx[6] += nByteLen >> 0x1d;
    if (nBitLo + nByteLen > 0x3f) {
      nProcessed = -nBitLo + 0x40;
      memcpy((void*)(nBitLo + 0x1c + (char*)pShaCtx), pData, nProcessed);
      SHA1_Transform(pShaCtx + 7, pShaCtx);
      for (nBufOffset = -nBitLo + 0x7f; nBufOffset < nByteLen; nBufOffset += 0x40) {
        SHA1_Transform((uint32_t*)((char*)pData + (nBufOffset - 0x3f)), pShaCtx);
        nProcessed += 0x40;
      }

      nBitLo = 0;
    } else {
      nProcessed = 0;
    }

    memcpy((void*)(nBitLo + 0x1c + (char*)pShaCtx), (void*)(nProcessed + (char*)pData), nByteLen - nProcessed);
}

void __fastcall SHA1_Final(uint8_t * pHashOut, uint32_t * pShaCtx) {
    // Static local variables (originally global data)
    static uint8_t gaSHA1FinalData[4] = { 0x80, 0x0, 0x0, 0x0 }; D2_STATIC_GUARD(gaSHA1FinalData, "Bnclient::SHA1::SHA1_Final::gaSHA1FinalData");

    uint8_t abLengthBE[8];
    uint32_t uVar1 = pShaCtx[6];
    abLengthBE[0] = (uint8_t)(uVar1 >> 0x18);
    abLengthBE[1] = (uint8_t)(uVar1 >> 0x10);
    abLengthBE[3] = (uint8_t)uVar1;
    uint32_t dwBitLen2 = pShaCtx[5];
    abLengthBE[2] = (uint8_t)(uVar1 >> 8);
    abLengthBE[4] = (uint8_t)(dwBitLen2 >> 0x18);
    abLengthBE[5] = (uint8_t)(dwBitLen2 >> 0x10);
    abLengthBE[6] = (uint8_t)(dwBitLen2 >> 8);
    abLengthBE[7] = (uint8_t)dwBitLen2;
    SHA1_Update(pShaCtx, gaSHA1FinalData, 1);
    uVar1 = pShaCtx[5];
    while ((uVar1 & 0x1f8) != 0x1c0) {
      SHA1_Update(pShaCtx, BnSend::gaBnSendRawBytesHeader, 1);
      uVar1 = pShaCtx[5];
    }

    SHA1_Update(pShaCtx, abLengthBE, 8);
    uVar1 = 0;
    do {
      dwBitLen2 = uVar1 + 1;
      pHashOut[uVar1] = (uint8_t)(*(uint32_t*)((char*)pShaCtx + (uVar1 & -4)) >> D2_SHIFT_COUNT(('\x03' - ((uint8_t)uVar1 & 3)) * '\b'));
      uVar1 = dwBitLen2;
    } while (dwBitLen2 < 0x14);
}

